// Genera clave automática: primera letra nombre + primera letra apellido + 2026
function generarClave(nombre){
  const p=nombre.trim().split(/\s+/);
  return ((p[0]?.[0]||"X")+(p[1]?.[0]||"X")+"2026").toUpperCase();
}

