const SUPA_URL = "https://eegczyrvfshaxnwehwbj.supabase.co";
const SUPA_KEY = "sb_publishable_mOeByTEAyqsVhEA5XQd_GQ_grVLgRol";

async function supaFetch(path, opts={}) {
  const preferParts = ["return=representation"];
  if(opts.prefer) preferParts.push(opts.prefer);
  const res = await fetch(SUPA_URL + "/rest/v1/" + path, {
    headers: {
      "apikey": SUPA_KEY,
      "Authorization": "Bearer " + SUPA_KEY,
      "Content-Type": "application/json",
      "Prefer": preferParts.join(","),
      ...opts.headers
    },
    method: opts.method || "GET",
    body: opts.body
  });
  if (!res.ok) {
    const e = await res.text();
    console.error("Supabase error:", path, e);
    // Devolver objeto de error estructurado para que el caller pueda inspeccionarlo
    try { return { _error: true, ...JSON.parse(e) }; } catch { return { _error: true, message: e }; }
  }
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

