function waMsgReserva(r, espacio, usuario) {
  const esp = espacio||{};
  const recInfo = r.esRec
    ? ("Recurrente: "+DIAS.filter(d=>r.dias?.includes(d.v)).map(d=>d.l).join(", ")+" | Periodo: "+fmt(r.fDesde)+" al "+fmt(r.fHasta))
    : ("Fecha: "+fmt(r.fecha));
  const reqs = (r.requerimientos||[]).map(q=>{
    const d=REQS.find(x=>x.id===q.id);
    return d?(q.detalle?d.label+": "+q.detalle:d.label):null;
  }).filter(Boolean).join(", ");
  return [
    "Nueva Reserva ISL",
    "Espacio: "+(esp.planta?esp.planta+" - ":"")+esp.nombre,
    recInfo,
    "Horario: "+r.hDesde+" a "+r.hHasta+" hs",
    "Responsable: "+r.responsable,
    r.equipo?"Equipo: "+r.equipo:"",
    r.cliente?"Cliente: "+r.cliente:"",
    r.personas?"Personas: "+r.personas:"",
    reqs?"Reqs: "+reqs:"",
    r.acomp?"REQUIERE ACOMPANAMIENTO DE RECEPCION":"",
    r.obs?"Obs: "+r.obs:"",
    "reservasisl.vercel.app"
  ].filter(Boolean).join("\n");
}

