// Verifica si una fecha es feriado
function esFeriado(fecha, feriados) {
  if(!feriados||!Array.isArray(feriados)) return null;
  return feriados.find(f=>f.fecha===fecha);
}

function horasDisponiblesDesde(reservas, espacioId, fecha, hMin, hMax) {
  const base = (hMin||hMax) ? HORAS.filter(h => (!hMin||h>=hMin) && (!hMax||h<hMax)) : HORAS;
  return base.filter(h => {
    const sig = HORAS[HORAS.indexOf(h)+1];
    if(!sig) return false;
    if(hMax && sig > hMax) return false;
    return !hayConflicto(reservas, espacioId, fecha, h, sig);
  });
}

