// ─── Formulario nuevo pedido cadete ───────────────────────────────────────────
function FormPedidoCadete({usuarios, pedidos, usuario, feriados, onSubmit}){
  const cadetes=usuarios.filter(u=>u.rol==="cadete"&&u.activo);
  const [f,setF]=useState({cadeteId:"",fecha:"",hora:"",remitente:usuario.nombre,desde:"",destinatario:"",hasta:"",destinosExtra:[],contenido:"",obs:"",imagenUrl:""});
  const [errs,setErrs]=useState({});
  const [preview,setPreview]=useState(null);
  const [remitoNum]=useState(()=>{
    const n=parseInt(localStorage.getItem(K_REMITO_NUM)||"0")+1;
    return n;
  });

  const validate=()=>{
    const e={};
    if(!f.cadeteId) e.cadete="Seleccioná un cadete";
    if(!f.fecha) e.fecha="Ingresá la fecha";
    if(!f.remitente.trim()) e.remitente="Requerido";
    if(!f.desde.trim()) e.desde="Requerido";
    if(!f.destinatario.trim()) e.destinatario="Requerido";
    if(!f.hasta.trim()) e.hasta="Requerido";
    if(!f.contenido.trim()) e.contenido="Requerido";
    if(!f.hora) e.hora="Seleccioná una hora";
    return e;
  };

  const handleImage=(e)=>{
    const file=e.target.files[0];
    if(!file) return;
    const reader=new FileReader();
    reader.onload=(ev)=>{setPreview(ev.target.result);setF(p=>({...p,imagenUrl:ev.target.result}));};
    reader.readAsDataURL(file);
  };

  const submit=()=>{
    const e=validate(); if(Object.keys(e).length){setErrs(e);return;}
    const numActual=remitoNum;
    localStorage.setItem(K_REMITO_NUM,String(numActual));
    // Save remito to registry
    const remitosActuales=JSON.parse(localStorage.getItem(K_REMITOS)||"[]");
    const nuevoRemito={num:numActual,fecha:f.fecha||new Date().toISOString().slice(0,10),remitente:f.remitente,destinatario:f.destinatario,desde:f.desde,hasta:f.hasta,contenido:f.contenido,obs:f.obs,creadoEn:fmtDT()};
    localStorage.setItem(K_REMITOS,JSON.stringify([nuevoRemito,...remitosActuales].slice(0,200)));
    const nuevoPedido={...f,id:uid(),usuarioId:usuario.id,estado:"pendiente",creadoEn:fmtDT(),remitoNum:numActual};
    onSubmit(nuevoPedido);
    setF({cadeteId:"",fecha:"",hora:"",remitente:usuario.nombre,desde:"",destinatario:"",hasta:"",destinosExtra:[],contenido:"",obs:"",imagenUrl:""});
    setPreview(null);setErrs({});
  };

  const INP="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-300 text-slate-700";
  const LB="block text-xs font-bold mb-1 uppercase tracking-wide";
  const er=k=>errs[k]?<p className="text-red-500 text-xs mt-0.5">{errs[k]}</p>:null;

  return(
    <div className="space-y-4">
      {/* Cadete */}
      <div>
        <label className={LB} style={{color:C.verde2}}>Cadete *</label>
        <div className="grid grid-cols-2 gap-2">
          {cadetes.map(c=>{
            const ferH=esFeriado(f.fecha,feriados);
            return(
              <button key={c.id} type="button" onClick={()=>setF(p=>({...p,cadeteId:c.id}))}
                className={"p-3 rounded-xl border-2 text-left transition-all "+(f.cadeteId===c.id?"border-transparent text-white":"border-slate-200 hover:border-green-400 bg-white")}
                style={f.cadeteId===c.id?{background:"linear-gradient(135deg,#1A1A1A,#333)"}:{}}>
                <p className={"font-bold text-sm "+(f.cadeteId===c.id?"text-white":"text-slate-800")}>{c.nombre}</p>
                <p className={"text-xs "+(f.cadeteId===c.id?"text-green-300":"text-slate-400")}>{c.hDesde||"09:00"} – {c.hHasta||"18:00"} hs</p>
              </button>
            );
          })}
        </div>
        {er("cadete")}
      </div>

      {/* Fecha + Hora */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <label className={LB} style={{color:C.verde2}}>Fecha de envío *</label>
          <input type="date" value={f.fecha} min={hoy()} onChange={ev=>setF(p=>({...p,fecha:ev.target.value}))} className={INP}/>
          {er("fecha")}
          {f.fecha&&esFeriado(f.fecha,feriados)&&(
            <p className="text-amber-600 text-xs mt-1 font-semibold">⚠️ Este día es feriado. Verificá disponibilidad del cadete.</p>
          )}
        </div>
        <div>
          <label className={LB} style={{color:C.verde2}}>Hora estimada *</label>
          <select value={f.hora||""} onChange={ev=>setF(p=>({...p,hora:ev.target.value}))} className={INP}>
            <option value="">Seleccioná...</option>
            {HORAS.slice(0,-1).map(h=><option key={h} value={h}>{h} hs</option>)}
          </select>
          {er("hora")}
        </div>
      </div>

      {/* Remitente + Desde */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <label className={LB} style={{color:C.verde2}}>Remitente *</label>
          <input type="text" value={f.remitente} onChange={ev=>setF(p=>({...p,remitente:ev.target.value}))} className={INP}/>{er("remitente")}
        </div>
        <div>
          <label className={LB} style={{color:C.verde2}}>Desde (dirección origen) *</label>
          <input type="text" value={f.desde} onChange={ev=>setF(p=>({...p,desde:ev.target.value}))} placeholder="Ej: Tucumán 2011, CABA" className={INP}/>{er("desde")}
        </div>
      </div>

      {/* Destinatario + Hasta */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <label className={LB} style={{color:C.verde2}}>Destinatario *</label>
          <input type="text" value={f.destinatario} onChange={ev=>setF(p=>({...p,destinatario:ev.target.value}))} className={INP}/>{er("destinatario")}
        </div>
        <div>
          <label className={LB} style={{color:C.verde2}}>Hasta (dirección destino) *</label>
          <input type="text" value={f.hasta} onChange={ev=>setF(p=>({...p,hasta:ev.target.value}))} placeholder="Ej: Av. Corrientes 1234, CABA" className={INP}/>{er("hasta")}
        </div>
      </div>

      {/* Destinos adicionales */}
      {(f.destinosExtra||[]).map((d,i)=>(
        <div key={i} className="rounded-xl p-3 border border-dashed border-slate-300" style={{background:"#F9FDF5"}}>
          <div className="flex items-center justify-between mb-2">
            <p className="text-xs font-bold uppercase" style={{color:C.verde2}}>Destino adicional {i+2}</p>
            <button type="button" onClick={()=>setF(p=>({...p,destinosExtra:(p.destinosExtra||[]).filter((_,j)=>j!==i)}))}
              className="text-xs text-red-400 hover:text-red-600 font-bold">✕ Quitar</button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className={LB} style={{color:C.verde2}}>Destinatario *</label>
              <input type="text" value={d.destinatario||""} placeholder="Nombre o empresa"
                onChange={ev=>setF(p=>({...p,destinosExtra:(p.destinosExtra||[]).map((x,j)=>j===i?{...x,destinatario:ev.target.value}:x)}))}
                className={INP}/>
            </div>
            <div>
              <label className={LB} style={{color:C.verde2}}>Dirección destino *</label>
              <input type="text" value={d.hasta||""} placeholder="Ej: Florida 123, CABA"
                onChange={ev=>setF(p=>({...p,destinosExtra:(p.destinosExtra||[]).map((x,j)=>j===i?{...x,hasta:ev.target.value}:x)}))}
                className={INP}/>
            </div>
          </div>
        </div>
      ))}
      {(f.destinosExtra||[]).length < 2&&(
        <button type="button"
          onClick={()=>setF(p=>({...p,destinosExtra:[...(p.destinosExtra||[]),{destinatario:"",hasta:""}]}))}
          className="flex items-center gap-2 text-sm font-semibold px-4 py-2 rounded-xl border border-dashed border-slate-300 hover:border-green-400 text-slate-500 hover:text-green-600 transition-all">
          ➕ Agregar destino adicional
        </button>
      )}

      {/* Contenido */}
      <div>
        <label className={LB} style={{color:C.verde2}}>Contenido *</label>
        <textarea rows={2} value={f.contenido} onChange={ev=>setF(p=>({...p,contenido:ev.target.value}))}
          placeholder="Descripción de lo que se envía" className={INP+" resize-none"}/>{er("contenido")}
      </div>

      {/* Observaciones */}
      <div>
        <label className={LB} style={{color:C.verde2}}>Observaciones</label>
        <textarea rows={2} value={f.obs} onChange={ev=>setF(p=>({...p,obs:ev.target.value}))}
          placeholder="Instrucciones especiales, urgencia, etc." className={INP+" resize-none"}/>
      </div>

      {/* Imagen remito */}
      <div>
        <label className={LB} style={{color:C.verde2}}>Imagen del remito (opcional)</label>
        <label className="flex items-center gap-3 cursor-pointer w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 transition-colors">
          <span className="px-3 py-1.5 rounded-lg text-xs font-bold text-white shrink-0" style={{background:C.verde2}}>
            Seleccionar archivo
          </span>
          <span className="text-slate-400 text-xs truncate">{preview?"Imagen cargada ✅":"Sin archivos seleccionados"}</span>
          <input type="file" accept="image/*" onChange={handleImage} className="hidden"/>
        </label>
        {preview&&(
          <div className="mt-2 relative">
            <img src={preview} alt="Preview" className="max-h-40 rounded-xl border border-slate-200"/>
            <button onClick={()=>{setPreview(null);setF(p=>({...p,imagenUrl:""}));}}
              className="absolute top-1 right-1 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">✕</button>
          </div>
        )}
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        <button onClick={submit} className="flex-1 py-3 rounded-xl text-white font-bold text-sm shadow-sm"
          style={{background:"linear-gradient(135deg,#1A1A1A,#333)"}}>
          📦 Confirmar pedido
        </button>
        {(f.remitente||f.contenido)&&(
          <GenerarRemito
            pedido={{...f,fecha:f.fecha||new Date().toISOString().slice(0,10)}}
            numero={remitoNum}/>
        )}
      </div>
    </div>
  );
}

// ─── Vista Cadete (sus pedidos) ────────────────────────────────────────────────
function VistaCadete({pedidos, usuarios, usuario, onAceptar, onRechazar, onCompletar}){
  const [verPedido,setVerPedido]=useState(null);
  const misPedidos=pedidos.filter(p=>p.cadeteId===usuario.id).sort((a,b)=>{
    const fa=a.esRec?a.fDesde:a.fecha||"";
    const fb=b.esRec?b.fDesde:b.fecha||"";
    return fb>fa?1:fb<fa?-1:0;
  });
  const pendientes=misPedidos.filter(p=>p.estado==="pendiente");
  const activos=misPedidos.filter(p=>p.estado==="aceptado");
  const historico=misPedidos.filter(p=>p.estado==="completado"||p.estado==="rechazado");

  const CardPedido=({p})=>(
    <div onClick={()=>setVerPedido(p)}
      className={"rounded-xl px-4 py-3 cursor-pointer border transition-all hover:shadow-sm "+(
        p.estado==="aceptado"?"border-green-300 bg-green-50":
        p.estado==="rechazado"?"border-red-200 bg-red-50 opacity-60":
        p.estado==="completado"?"border-slate-200 bg-slate-50 opacity-60":
        "border-amber-300 bg-amber-50"
      )}>
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs font-bold" style={{color:p.estado==="aceptado"?"#6C9F51":p.estado==="rechazado"?"#DC2626":p.estado==="completado"?"#888":"#E07B00"}}>
          {p.estado==="aceptado"?"✅ Aceptado":p.estado==="rechazado"?"❌ Rechazado":p.estado==="completado"?"☑️ Completado":"⏳ Pendiente — tocá para gestionar"}
        </span>
        <span className="text-xs text-slate-400">{fmt(p.fecha)}</span>
      </div>
      <p className="font-semibold text-slate-800 text-sm">📦 {p.contenido}</p>
      <p className="text-xs text-slate-500">{p.desde} → {p.hasta}</p>
    </div>
  );

  return(
    <div className="space-y-5">
      {pendientes.length>0&&(
        <div>
          <h3 className="text-sm font-bold mb-2 text-amber-600">⏳ Pendientes de respuesta ({pendientes.length})</h3>
          <div className="space-y-2">{pendientes.map(p=><CardPedido key={p.id} p={p}/>)}</div>
        </div>
      )}
      {activos.length>0&&(
        <div>
          <h3 className="text-sm font-bold mb-2" style={{color:C.verde}}>✅ Aceptados — en curso ({activos.length})</h3>
          <div className="space-y-2">{activos.map(p=><CardPedido key={p.id} p={p}/>)}</div>
        </div>
      )}
      {historico.length>0&&(
        <div>
          <h3 className="text-sm font-bold mb-2 text-slate-400">Historial ({historico.length})</h3>
          <div className="space-y-2">{historico.map(p=><CardPedido key={p.id} p={p}/>)}</div>
        </div>
      )}
      {misPedidos.length===0&&(
        <div className="text-center py-12 text-slate-400">
          <p className="text-3xl mb-2">📦</p>
          <p className="text-sm">No tenés pedidos asignados</p>
        </div>
      )}
      {verPedido&&(
        <ModalPedido pedido={verPedido} usuarios={usuarios} usuario={usuario}
          onAceptar={async(id)=>{await onAceptar(id);setVerPedido(null);}}
          onRechazar={async(id,obs)=>{await onRechazar(id,obs);setVerPedido(null);}}
          onCompletar={async(id,obs,foto)=>{await onCompletar(id,obs,foto);setVerPedido(null);}}
          onClose={()=>setVerPedido(null)}/>
      )}
    </div>
  );
}

// ─── Cambiar clave ───────────────────────────────────────────────────────────
function CambiarClave({usuario, onGuardar}){
  const [actual,setActual]=useState("");
  const [nueva,setNueva]=useState("");
  const [confirma,setConfirma]=useState("");
  const [err,setErr]=useState("");
  const [ok,setOk]=useState(false);

  const guardar=()=>{
    const claveActual=(usuario.clave||generarClave(usuario.nombre)).toUpperCase();
    if(actual.toUpperCase()!==claveActual){setErr("La clave actual es incorrecta");return;}
    if(nueva.length<4){setErr("La nueva clave debe tener al menos 4 caracteres");return;}
    if(nueva!==confirma){setErr("Las claves no coinciden");return;}
    onGuardar(nueva.toUpperCase());
    setActual("");setNueva("");setConfirma("");setErr("");setOk(true);
    setTimeout(()=>setOk(false),3000);
  };

  const INP="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-300";
  return(
    <div className="max-w-sm space-y-4">
      <div className="bg-white rounded-xl p-4 border border-slate-200 text-sm text-slate-600 space-y-1">
        <p>👤 <b>{usuario.nombre}</b></p>
        <p className="text-xs text-slate-400">Clave inicial: {generarClave(usuario.nombre)}</p>
      </div>
      <div>
        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Clave actual</label>
        <input type="password" value={actual} onChange={e=>setActual(e.target.value)} className={INP} placeholder="Tu clave actual"/>
      </div>
      <div>
        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nueva clave</label>
        <input type="password" value={nueva} onChange={e=>setNueva(e.target.value)} className={INP} placeholder="Mínimo 4 caracteres"/>
      </div>
      <div>
        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Confirmar nueva clave</label>
        <input type="password" value={confirma} onChange={e=>setConfirma(e.target.value)} className={INP} placeholder="Repetí la nueva clave"
          onKeyDown={e=>e.key==="Enter"&&guardar()}/>
      </div>
      {err&&<p className="text-red-500 text-sm font-semibold">⚠️ {err}</p>}
      {ok&&<p className="text-green-600 text-sm font-semibold">✅ Clave actualizada correctamente</p>}
      <button onClick={guardar} className="w-full py-3 rounded-xl text-white font-bold text-sm"
        style={{background:"linear-gradient(135deg,#6C9F51,#9EC3E7)"}}>
        Guardar nueva clave
      </button>
    </div>
  );
}

export default function App(){
  const [reservas,setReservas]=useState([]);
  const [espacios,setEspacios]=useState(DEFAULT_ESPACIOS);
  const [usuarios,setUsuarios]=useState(DEFAULT_USUARIOS);
  const [feriados,setFeriados]=useState(FERIADOS_DEFAULT);
  const [loading,setLoading]=useState(true);
  const [usuario,setUsuario]=useState(null);
  const [vista,setVista]=useState("reserva");
  const [subReserva,setSub]=useState("sala");
  const [subOcup,setSubOcup]=useState("diaria");
  const [subCad,setSubCad]=useState("pedidos");

  // Refrescar reservas al abrir el formulario o la agenda
  useEffect(()=>{
    if(vista==="reserva"||vista==="ocup"||vista==="recepcion") {
      refrescarReservas();
    }
  },[vista]);
  const [subConfig,setSubConfig]=useState("espacios");
  const [mail,setMail]=useState(null);
  const [menuAbierto,setMenuAbierto]=useState(false);
  const [toast,setToast]=useState(null);
  const [excepcionModal,setExcepcionModal]=useState(null);
  const [pedidos,setPedidos]=useState([]);
  const [verPedidoModal,setVerPedidoModal]=useState(null);

  // Función para refrescar reservas (usada en montaje, foco y apertura de formulario)
  const refrescarReservas = useCallback(async()=>{
    const r = await dbGetReservas();
    if(r && r.length>0) setReservas(r.map(mapReserva));
  },[]);

  useEffect(()=>{
    Promise.all([dbGetReservas(), dbGetEspacios(), dbGetUsuarios(), stGet(K_FERIADOS), dbGetPedidos()]).then(([r,e,u,fer,ped])=>{
      if(r && r.length>0) setReservas(r.map(mapReserva));
      if(e && e.length>0) setEspacios(e);
      if(u && u.length>0) setUsuarios(u);
      if(fer) setFeriados(fer);
      if(ped && ped.length>0) setPedidos(ped);
      setLoading(false);
    });
    // Refrescar cuando la pestaña vuelve al foco
    const onFocus = ()=>refrescarReservas();
    const onVisible = ()=>{ if(document.visibilityState==="visible") refrescarReservas(); };
    window.addEventListener("focus", onFocus);
    document.addEventListener("visibilitychange", onVisible);
    return ()=>{
      window.removeEventListener("focus", onFocus);
      document.removeEventListener("visibilitychange", onVisible);
    };
  },[]);

  const showToast=(msg,c="green")=>{setToast({msg,c});setTimeout(()=>setToast(null),3500);};

  const agregar=useCallback(async r=>{
    try {
      await dbInsertReserva(r);
      setReservas(p=>[r,...p]);
      setMail(r);
      showToast("✅ Reserva registrada. Notificación enviada.");
    } catch(e) {
      if(e.code==="23P01") {
        showToast("⚠️ Ese horario se acaba de ocupar. Actualizá la agenda y elegí otro.","red");
        const frescas=await dbGetReservas();
        if(frescas&&frescas.length>0) setReservas(frescas.map(mapReserva));
      } else {
        showToast("❌ Error al guardar la reserva. Intentá de nuevo.","red");
      }
    }
  },[]);

  const editar=useCallback(async(id,cambios)=>{
    await dbUpdateReserva(id, cambios);
    setReservas(p=>p.map(r=>r.id===id?{...r,...cambios}:r));
    showToast(cambios.estado==="anulada"?"Reserva anulada":"Reserva modificada",cambios.estado==="anulada"?"red":"green");
  },[]);

  const guardarEsp=useCallback(async e=>{
    setEspacios(e);
    await dbSaveEspacios(e);
    showToast("Espacios guardados");
  },[]);
  const guardarUsr=useCallback(async u=>{
    setUsuarios(u);
    await dbSaveUsuarios(u);
    // Reload from DB to get latest data including new users
    const fresh = await dbGetUsuarios();
    if(fresh && fresh.length>0) setUsuarios(fresh);
    showToast("Usuarios guardados");
  },[]);

  const guardarFeriados=useCallback(async f=>{
    setFeriados(f);
    await stSet(K_FERIADOS,f);
    showToast("Feriados guardados");
  },[]);

  const agregarPedido=useCallback(async p=>{
    await dbInsertPedido(p);
    setPedidos(prev=>[p,...prev]);
    showToast("✅ Pedido de cadetería registrado exitosamente");
    // WA al cadete
    const cadete=usuarios.find(u=>u.id===p.cadeteId);
    if(cadete?.cel){
      const msg=waMsgPedidoCadete(p,cadete.nombre,usuario.nombre);
      window.open("https://wa.me/"+cadete.cel+"?text="+encodeURIComponent(msg),"_blank");
    }
    showToast("✅ Pedido cargado. WhatsApp enviado al cadete.");
  },[pedidos,usuarios,usuario]);

  const actualizarPedido=useCallback(async(id,cambios)=>{
    await dbActualizarPedido(id,cambios);
    setPedidos(prev=>prev.map(p=>p.id===id?{...p,...cambios}:p));
  },[]);

  const aceptarPedido=useCallback(async(id)=>{
    const p=pedidos.find(x=>x.id===id);
    if(!p) return;
    await actualizarPedido(id,{estado:"aceptado",aceptadoEn:fmtDT()});
    // WA al solicitante
    const sol=usuarios.find(u=>u.id===p.usuarioId);
    const msgAcep="✅ Tu pedido fue ACEPTADO\nContenido: "+p.contenido+"\nCadete: "+usuario.nombre+"\nFecha: "+fmt(p.fecha)+(p.hora?"  Hora: "+p.hora+" hs":"")+"\n\nreservasisl.vercel.app";
    if(sol?.cel){
      window.open("https://wa.me/"+sol.cel+"?text="+encodeURIComponent(msgAcep),"_blank");
    } else {
      window.open("https://wa.me/"+WA_RECEPCION+"?text="+encodeURIComponent("Aviso: pedido ACEPTADO por "+usuario.nombre+"\n"+msgAcep),"_blank");
    }
    showToast("Pedido aceptado");
  },[pedidos,usuarios,usuario,actualizarPedido]);

  const rechazarPedido=useCallback(async(id,obs)=>{
    const p=pedidos.find(x=>x.id===id);
    if(!p) return;
    await actualizarPedido(id,{estado:"rechazado",obsRechazo:obs,rechazadoEn:fmtDT()});
    const sol=usuarios.find(u=>u.id===p.usuarioId);
    const msgRech="❌ Tu pedido fue RECHAZADO\nContenido: "+p.contenido+"\nCadete: "+usuario.nombre+(obs?"\nMotivo: "+obs:"")+"\n\nreservasisl.vercel.app";
    window.open("https://wa.me/"+(sol?.cel||WA_RECEPCION)+"?text="+encodeURIComponent(msgRech),"_blank");
    showToast("Pedido rechazado","red");
  },[pedidos,usuarios,usuario,actualizarPedido]);

  const completarPedido=useCallback(async(id,obs,fotoUrl)=>{
    const p=pedidos.find(x=>x.id===id);
    // 1. Guardar estado
    await actualizarPedido(id,{estado:"completado",obsCierre:obs,completadoEn:fmtDT()});
    // 2. Guardar foto ANTES de abrir WA
    if(fotoUrl){
      try{
        console.log("Guardando foto:",Math.round(fotoUrl.length/1024),"KB");
        const res=await fetch(SUPA_URL+"/rest/v1/pedidos?id=eq."+id,{
          method:"PATCH",
          headers:{
            "apikey":SUPA_KEY,
            "Authorization":"Bearer "+SUPA_KEY,
            "Content-Type":"application/json",
            "Prefer":"return=representation"
          },
          body:JSON.stringify({imagen_cierre:fotoUrl})
        });
        console.log("Foto guardada, status:",res.status);
        if(res.ok) setPedidos(prev=>prev.map(x=>x.id===id?{...x,imagenCierre:fotoUrl}:x));
        else { const err=await res.text(); console.error("Error Supabase:",err); }
      }catch(e){console.error("Error fetch foto:",e);}
    }
    // 3. Recién ahora abrir WhatsApp
    showToast("Trámite cerrado ✅");
    if(p){
      const sol=usuarios.find(u=>u.id===p.usuarioId);
      const msgCierre="☑️ Trámite completado\nPedido #"+p.id.slice(-5).toUpperCase()+"\nContenido: "+p.contenido+"\nCadete: "+usuario.nombre+(obs?"\nObs: "+obs:"")+(fotoUrl?"\n📷 Remito firmado en el sistema":"")+"\n\nreservasisl.vercel.app";
      setTimeout(()=>window.open("https://wa.me/"+(sol?.cel||WA_RECEPCION)+"?text="+encodeURIComponent(msgCierre),"_blank"),500);
    }
  },[pedidos,usuarios,usuario,actualizarPedido]);

  const borrarReservas=useCallback(async ids=>{
    const nuevas=reservas.filter(r=>!ids.includes(r.id));
    setReservas(nuevas);
    // Borrar de Supabase
    for(const id of ids){
      await supaFetch("reservas?id=eq."+id,{method:"DELETE",prefer:""});
    }
    showToast(`${ids.length} reservas eliminadas`,"red");
  },[reservas]);

  const guardarExcepcion=useCallback(async(reservaId,fecha,hD,hH,obs)=>{
    // Agrega una excepción modificada: excluye esa fecha y crea reserva puntual
    const reserva=reservas.find(r=>r.id===reservaId);
    if(!reserva) return;
    // Excluir fecha de la serie
    const excls=[...(reserva.exclusiones||[]),fecha];
    await editar(reservaId,{exclusiones:excls,historial:[...(reserva.historial||[]),{accion:`Excepción creada para ${fmt(fecha)}: horario modificado`,por:usuario.nombre,fecha:fmtDT()}]});
    // Crear reserva puntual para esa fecha con nuevo horario
    const nueva={...reserva,id:uid(),esRec:false,fecha,hDesde:hD,hHasta:hH,obs:obs||(reserva.obs||""),
      creadoEn:fmtDT(),historial:[{accion:`Excepción de recurrente ${reservaId.slice(-6).toUpperCase()}`,por:usuario.nombre,fecha:fmtDT()}]};
    await agregar(nueva);
    setExcepcionModal(null);
    showToast("Excepción guardada para "+fmt(fecha));
  },[reservas,usuario,editar,agregar]);

  const excluirFecha=useCallback(async(reservaId,fecha,motivo)=>{
    const reserva=reservas.find(r=>r.id===reservaId);
    if(!reserva) return;
    const excls=[...(reserva.exclusiones||[]),fecha];
    await editar(reservaId,{exclusiones:excls,historial:[...(reserva.historial||[]),{accion:`Fecha excluida: ${fmt(fecha)}${motivo?" ("+motivo+")":""}`,por:usuario.nombre,fecha:fmtDT()}]});
    setExcepcionModal(null);
    showToast("Fecha "+fmt(fecha)+" excluida de la serie");
  },[reservas,usuario,editar]);

  const isAdmin=usuario?.rol==="admin";
  const acompPend=reservas.filter(r=>r.estado!=="anulada"&&r.acomp).length;

  if(loading) return(
    <div className="min-h-screen flex items-center justify-center" style={{background:"linear-gradient(135deg,#6C9F51,#9EC3E7)"}}>
      <div className="text-center">
        <div className="w-10 h-10 border-4 border-white border-t-transparent rounded-full animate-spin mx-auto mb-3"/>
        <p className="text-white text-sm font-semibold">Cargando...</p>
      </div>
    </div>
  );

  if(!usuario) return <Login usuarios={usuarios} onLogin={(id,esInicial)=>{
    const u=usuarios.find(x=>x.id===id); if(u){
      setUsuario(u);
      if(u.rol==="gestor"||u.rol==="cadete") setSubOcup("cadetes");
      else setSubOcup("diaria");
      if(esInicial){
        setVista("miclave");
        setTimeout(()=>showToast("⚠️ Cambiá tu clave inicial antes de continuar","red"),400);
      } else {
        setVista(u.rol==="cadete"?"miscadete":u.rol==="gestor"?"cadetes":"reserva");
      }
    }
  }}/>;

  const isCadete=usuario.rol==="cadete";
  const isGestor=usuario.rol==="gestor";
  const isLider=usuario.rol==="lider";
  const pedPend=pedidos.filter(p=>p.cadeteId===usuario.id&&p.estado==="pendiente").length;

  const NAV_LIDER=[
    {k:"reserva", icon:"📅", label:"Nueva reserva"},
    {k:"mis",     icon:"📋", label:"Mis reservas"},
    {k:"ocup",    icon:"📊", label:"Gestión de Agenda"},
    {k:"cadetes", icon:"🚴", label:"Cadetería"},
    {k:"miclave", icon:"🔑", label:"Mi clave"},
  ];
  const NAV_ADMIN=[
    {k:"reserva",   icon:"📅", label:"Nueva reserva"},
    {k:"recepcion", icon:"🛎️", label:"Recepción", badge:acompPend},
    {k:"ocup",      icon:"📊", label:"Gestión de Agenda"},
    {k:"cadetes",   icon:"🚴", label:"Cadetería"},
    {k:"config",    icon:"⚙️", label:"Configurar"},
  ];
  const NAV_GESTOR=[
    {k:"cadetes",  icon:"🚴", label:"Cadetería"},
    {k:"ocup",     icon:"📊", label:"Gestión de Agenda"},
    {k:"miclave",  icon:"🔑", label:"Mi clave"},
  ];
  const NAV_CADETE=[
    {k:"miscadete", icon:"📦", label:"Mis pedidos", badge:pedPend},
    {k:"ocup",      icon:"📊", label:"Gestión de Agenda"},
    {k:"miclave",   icon:"🔑", label:"Mi clave"},
  ];
  const NAV=isAdmin?NAV_ADMIN:isCadete?NAV_CADETE:isGestor?NAV_GESTOR:NAV_LIDER;

  return(
    <div className="flex flex-col min-h-screen font-sans" style={{background:"#F5F5F5",fontSize:"15px"}}>

      {/* ── HEADER NEGRO ─────────────────────────────────────── */}
      <header className="fixed top-0 left-0 right-0 z-40 flex items-center justify-between shadow-lg" style={{background:"#141414",height:"64px",borderBottom:"1px solid #2A2A2A",padding:"0 20px"}}>
        <div className="flex items-center gap-3">
          {/* Hamburger solo en mobile */}
          <button className="md:hidden text-white text-2xl mr-2 leading-none" onClick={()=>setMenuAbierto(p=>!p)}>☰</button>
          {/* Logo solo en mobile (en desktop está en el sidebar) */}
          <div className="md:hidden">
            <ISLLogo size={0.65} onDark={true} showSub={false}/>
          </div>
          {/* Espacio reservado en desktop para que el contenido no quede pegado */}
          <div className="hidden md:block" style={{width:"10px"}}/>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-right hidden sm:block">
            <p className="text-white font-semibold" style={{fontSize:"15px"}}>{usuario.nombre}</p>
            <p className="text-xs" style={{color:C.azul}}>{isAdmin?"Admin / Recepción":isCadete?"Cadete":isGestor?"Gestor":"Líder"}</p>
          </div>
          <button onClick={()=>{setUsuario(null);setVista("reserva");setMenuAbierto(false);}}
            className="text-white font-semibold transition-colors px-4 py-2 rounded-lg text-sm"
            style={{border:"1px solid #444",background:"transparent"}}
            onMouseEnter={e=>e.currentTarget.style.background="#2A2A2A"}
            onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
            Salir
          </button>
        </div>
      </header>

      <div className="flex" style={{paddingTop:"64px",minHeight:"calc(100vh - 64px)"}}>

        {/* ── OVERLAY mobile ───────────────────────────────────── */}
        {menuAbierto&&<div className="fixed inset-0 bg-black/50 z-30 md:hidden" onClick={()=>setMenuAbierto(false)}/>}

        {/* ── SIDEBAR ──────────────────────────────────────────── */}
        <aside className={
          "fixed md:sticky top-0 left-0 z-30 flex flex-col transition-transform duration-200 "
          +(menuAbierto?"translate-x-0":"-translate-x-full md:translate-x-0")
        } style={{background:"#181818",width:"240px",height:"100vh",paddingTop:"0",flexShrink:0,borderRight:"1px solid #2A2A2A"}}>

          {/* Logo grande arriba */}
          <div className="flex items-center justify-center px-4" style={{borderBottom:"1px solid #2A2A2A",background:"#141414",height:"64px"}}>
            <ISLLogo size={0.95} onDark={true} showSub={true}/>
          </div>

          {/* Avatar solo con inicial y rol */}
          <div className="px-4 py-3 flex items-center gap-3" style={{borderBottom:"1px solid #2A2A2A"}}>
            <div className="w-8 h-8 rounded-full flex items-center justify-center text-white font-bold text-sm shrink-0"
              style={{background:"linear-gradient(135deg,#6C9F51,#9EC3E7)"}}>
              {usuario.nombre.charAt(0)}
            </div>
            <p className="text-xs" style={{color:"#9EC3E7"}}>{isAdmin?"Admin / Recepción":isCadete?"Cadete":isGestor?"Gestor":"Líder"}</p>
          </div>

          {/* Nav items */}
          <nav className="flex-1 py-2 overflow-y-auto">
            {NAV.map(n=>{
              const active = vista===n.k;
              return(
                <button key={n.k} onClick={()=>{setVista(n.k);setMenuAbierto(false);}}
                  className="relative w-full flex items-center gap-3 px-4 py-2.5 text-left transition-all group"
                  style={{
                    background: active?"linear-gradient(90deg,rgba(161,190,80,0.18),rgba(158,195,231,0.08))":"transparent",
                    borderLeft: active?"3px solid #A1BE50":"3px solid transparent",
                    marginBottom:"1px",
                  }}>
                  <span className="text-xl w-7 text-center" style={{filter:active?"none":"grayscale(0.3)"}}>{n.icon}</span>
                  <span className="text-sm font-semibold" style={{color:active?"#A1BE50":"#AAAAAA"}}>{n.label}</span>
                  {n.badge>0&&(
                    <span className="ml-auto text-white text-[10px] font-bold rounded-full w-5 h-5 flex items-center justify-center" style={{background:"#E07B00"}}>{n.badge}</span>
                  )}
                </button>
              );
            })}
          </nav>

          {/* Footer */}
          <div className="px-5 py-3" style={{borderTop:"1px solid #2A2A2A"}}>
            <p className="text-[11px] text-center" style={{color:"#444"}}>ISL · v2.0 · 2026</p>
          </div>
        </aside>

        {/* ── CONTENIDO PRINCIPAL ──────────────────────────────── */}
        <main className="flex-1 min-w-0 p-5 md:p-7" style={{maxWidth:"1200px"}}>

          {vista==="reserva"&&(
            <div className="space-y-4">
              <>
                  <h1 className="text-xl font-bold" style={{color:"#111"}}>Nueva reserva</h1>
                  <div className="flex gap-2">
                    {[{k:"sala",l:"🚪 Sala"},{k:"notebook",l:"💻 Notebook"}].map(t=>(
                      <button key={t.k} onClick={()=>setSub(t.k)}
                        className={"px-5 py-2.5 rounded-xl text-sm font-bold transition-all "+(subReserva===t.k?"text-white shadow-md":"bg-white text-slate-600 border border-slate-200 hover:bg-slate-50")}
                        style={subReserva===t.k?{background:"linear-gradient(135deg,#6C9F51,#9EC3E7)"}:{}}>
                        {t.l}
                      </button>
                    ))}
                  </div>
                  <div>
                    {subReserva==="sala"
                      ?<FormSala espacios={espacios} reservas={reservas} usuario={usuario} onSubmit={agregar}/>
                      :<FormNB   espacios={espacios} reservas={reservas} usuario={usuario} onSubmit={agregar}/>}
                  </div>
              </>
            </div>
          )}

          {vista==="mis"&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <h1 className="text-xl font-bold mb-5" style={{color:"#111"}}>Mis reservas</h1>
              <MisReservas reservas={reservas} espacios={espacios} usuario={usuario} onEditar={editar}/>
            </div>
          )}

          {vista==="recepcion"&&isAdmin&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <h1 className="text-xl font-bold mb-5" style={{color:"#111"}}>Panel de Recepción</h1>
              <PanelRec reservas={reservas} espacios={espacios} usuarios={usuarios} usuarioActual={usuario} onEditar={editar} onAgregar={agregar}/>
            </div>
          )}

          {vista==="ocup"&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <div className="flex items-center gap-3 mb-5 flex-wrap">
                <h1 className="text-xl font-bold" style={{color:"#111"}}>Gestión de Agenda</h1>
                <div className="flex gap-1 ml-auto p-1 bg-slate-100 rounded-xl flex-wrap">
                  {(isAdmin||isLider?[{k:"diaria",l:"🚪 Salas/NB"},{k:"semanal",l:"📅 Semanal"},{k:"cadetes",l:"🚴 Cadetes"}]:[{k:"cadetes",l:"🚴 Cadetes"}]).map(t=>(
                    <button key={t.k} onClick={()=>setSubOcup(t.k)}
                      className={"px-3 py-1.5 rounded-lg text-sm font-bold "+(subOcup===t.k?"text-white":"text-slate-600")}
                      style={subOcup===t.k?{background:C.verde2}:{}}>
                      {t.l}
                    </button>
                  ))}
                </div>
              </div>
              {subOcup==="diaria"&&(
                <GrillaDiaria reservas={reservas} espacios={espacios} feriados={feriados}
                   onEditarExcepcion={isAdmin?(r,f)=>setExcepcionModal({reserva:r,fecha:f}):null}/>
              )}
              {subOcup==="semanal"&&(
                <GrillaSemanal reservas={reservas} espacios={espacios} feriados={feriados}/>
              )}
              {subOcup==="cadetes"&&(
                <GrillaCadetes pedidos={pedidos} usuarios={usuarios} feriados={feriados}
                  isAdmin={isAdmin} isGestor={isGestor}
                  onVerPedido={p=>setVerPedidoModal(p)}/>
              )}
              {excepcionModal&&(
                <ModalExcepcion
                  reserva={excepcionModal.reserva} fecha={excepcionModal.fecha}
                  espacios={espacios} reservas={reservas} usuario={usuario}
                  onGuardar={guardarExcepcion}
                  onExcluir={excluirFecha}
                  onClose={()=>setExcepcionModal(null)}/>
              )}
              {verPedidoModal&&subOcup==="cadetes"&&(
                <ModalPedido pedido={verPedidoModal} usuarios={usuarios} usuario={usuario}
                  onAceptar={async(id)=>{await aceptarPedido(id);setVerPedidoModal(null);}}
                  onRechazar={async(id,obs)=>{await rechazarPedido(id,obs);setVerPedidoModal(null);}}
                  onCompletar={async(id,obs,foto)=>{await completarPedido(id,obs,foto);setVerPedidoModal(null);}}
                  onClose={()=>setVerPedidoModal(null)}/>
              )}
            </div>
          )}

          {vista==="nuevopedido"&&isGestor&&(
            <div className="space-y-4">
              <h1 className="text-xl font-bold" style={{color:"#111"}}>Nuevo pedido de cadetería</h1>
              <FormPedidoCadete usuario={usuario} usuarios={usuarios} pedidos={pedidos} feriados={feriados}
                onSubmit={async p=>{await agregarPedido(p);setVista("cadetes");showToast("✅ Su pedido ha sido cargado exitosamente");}}/>
            </div>
          )}

          {(vista==="cadetes")&&!isCadete&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <div className="flex items-center justify-between mb-5 flex-wrap gap-3">
                <h1 className="text-xl font-bold" style={{color:"#111"}}>🚴 Cadetería</h1>
                <div className="flex gap-2">
                  {(isGestor?[{k:"pedidos",l:"📦 Pedidos"},{k:"nuevopedido",l:"➕ Nuevo pedido"},{k:"firmados",l:"📷 Firmados"}]:[{k:"pedidos",l:"📦 Pedidos"},{k:"firmados",l:"📷 Firmados"}]).map(t=>(
                    <button key={t.k} onClick={()=>setSubCad(t.k)}
                      className={"px-3 py-1.5 rounded-xl text-sm font-bold transition-all "+(subCad===t.k?"text-white":"bg-white text-slate-600 border border-slate-200")}
                      style={subCad===t.k?{background:"linear-gradient(135deg,#6C9F51,#9EC3E7)"}:{}}>
                      {t.l}
                    </button>
                  ))}
                </div>
              </div>
              {subCad==="firmados"&&<RemitasFirmadas pedidos={pedidos} usuarios={usuarios}/>}
              {subCad==="nuevopedido"&&isGestor&&(
                <FormPedidoCadete usuario={usuario} usuarios={usuarios} pedidos={pedidos} feriados={feriados}
                  onSubmit={async p=>{await agregarPedido(p);setSubCad("pedidos");}}/>
              )}
              {subCad==="pedidos"&&(
                <>
                  <p className="text-sm text-slate-500 mb-4">La agenda de cadetes está en <b>Gestión de Agenda → 🚴 Cadetes</b></p>
                  <div className="border-t border-slate-200 pt-4">
                    <h2 className="text-base font-bold mb-3" style={{color:"#111"}}>Nuevo pedido</h2>
                    <FormPedidoCadete usuarios={usuarios} pedidos={pedidos} usuario={usuario}
                      feriados={feriados} onSubmit={agregarPedido}/>
                  </div>
                </>
              )}

              {/* Pedidos recientes */}
              {subCad==="pedidos"&&pedidos.filter(p=>p.estado!=="cancelado").length>0&&(
                <div className="mb-6">
                  <div className="flex items-center justify-between mb-3">
                    <h2 className="text-base font-bold" style={{color:"#111"}}>Pedidos recientes</h2>
                  </div>
                  <div className="space-y-2">
                    {pedidos.slice(0,5).map(p=>{
                      const cadete=usuarios.find(u=>u.id===p.cadeteId)||{};
                      return(
                        <div key={p.id} onClick={()=>setVerPedidoModal(p)}
                          className={"flex items-center gap-3 p-3 rounded-xl border cursor-pointer hover:shadow-sm transition-all "+(
                            p.estado==="aceptado"?"bg-green-50 border-green-200":
                            p.estado==="rechazado"?"bg-red-50 border-red-200 opacity-60":
                            p.estado==="completado"?"bg-slate-50 border-slate-200 opacity-60":
                            "bg-amber-50 border-amber-200"
                          )}>
                          <div className="w-8 h-8 rounded-full flex items-center justify-center text-white font-bold text-xs shrink-0"
                            style={{background:"#575958"}}>
                            {cadete.nombre?.charAt(0)||"?"}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <span className="font-semibold text-sm text-slate-800">{cadete.nombre||"Cadete"}</span>
                              <span className="text-xs text-slate-400">{fmt(p.fecha)}</span>
                              <span className={"text-xs font-bold px-2 py-0.5 rounded-full "+(
                                p.estado==="aceptado"?"bg-green-100 text-green-700":
                                p.estado==="rechazado"?"bg-red-100 text-red-700":
                                p.estado==="completado"?"bg-slate-100 text-slate-600":
                                "bg-amber-100 text-amber-700"
                              )}>
                                {p.estado==="aceptado"?"✅ Aceptado":p.estado==="rechazado"?"❌ Rechazado":p.estado==="completado"?"☑️ Completado":"⏳ Pendiente"}
                              </span>
                            </div>
                            <p className="text-xs text-slate-500 truncate">📦 {p.contenido} · {p.desde} → {p.hasta}</p>
                          </div>
                          <span className="text-slate-300 text-xs font-mono">#{p.id.slice(-5).toUpperCase()}</span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}



              {verPedidoModal&&(
                <ModalPedido pedido={verPedidoModal} usuarios={usuarios} usuario={usuario}
                  onAceptar={async(id)=>{await aceptarPedido(id);setVerPedidoModal(null);}}
                  onRechazar={async(id,obs)=>{await rechazarPedido(id,obs);setVerPedidoModal(null);}}
                  onCompletar={async(id,obs,foto)=>{await completarPedido(id,obs,foto);setVerPedidoModal(null);}}
                  onClose={()=>setVerPedidoModal(null)}/>
              )}
            </div>
          )}

          {vista==="miscadete"&&isCadete&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <h1 className="text-xl font-bold mb-5" style={{color:"#111"}}>📦 Mis pedidos</h1>
              <VistaCadete pedidos={pedidos} usuarios={usuarios} usuario={usuario}
                onAceptar={aceptarPedido}
                onRechazar={rechazarPedido}
                onCompletar={completarPedido}/>
            </div>
          )}

          {vista==="miclave"&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <h1 className="text-xl font-bold mb-5" style={{color:"#111"}}>🔑 Cambiar mi clave</h1>
              {usuario&&(usuario.clave||"").toUpperCase()===generarClave(usuario.nombre).toUpperCase()&&(
                <div className="rounded-xl p-3 mb-4 text-sm font-semibold" style={{background:"#FEF3C7",color:"#92400E",border:"1px solid #F59E0B"}}>
                  ⚠️ Estás usando la clave inicial. Cambiala para mayor seguridad.
                </div>
              )}
              <CambiarClave usuario={usuario} onGuardar={async(nuevaClave)=>{
                const nuevos=usuarios.map(u=>u.id===usuario.id?{...u,clave:nuevaClave}:u);
                await guardarUsr(nuevos);
                showToast("✅ Clave actualizada correctamente");
              }}/>
            </div>
          )}

          {vista==="config"&&isAdmin&&(
            <div className="rounded-2xl shadow-sm p-6" style={{background:"#EEF5E0",border:"1px solid #D4E8B0"}}>
              <h1 className="text-xl font-bold mb-5" style={{color:"#111"}}>Configuración</h1>
              <div className="flex gap-2 mb-5 flex-wrap">
                {[{k:"espacios",l:"⚙️ Espacios"},{k:"usuarios",l:"👥 Usuarios"},{k:"feriados",l:"🏖️ Feriados"},{k:"remitos",l:"📄 Remitos"},{k:"firmados",l:"📷 Firmados"},{k:"borrado",l:"🗑️ Borrado"}].map(t=>(
                  <button key={t.k} onClick={()=>setSubConfig(t.k)}
                    className={"px-4 py-2 rounded-xl text-sm font-bold transition-all "+(subConfig===t.k?"text-white":"bg-slate-100 text-slate-600 hover:bg-slate-200")}
                    style={subConfig===t.k?{background:t.k==="borrado"?"#DC2626":C.verde}:{}}>
                    {t.l}
                  </button>
                ))}
              </div>
              {subConfig==="espacios"&&<ConfigEspacios espacios={espacios} onSave={guardarEsp}/>}
              {subConfig==="usuarios"&&<ConfigUsuarios usuarios={usuarios} onSave={guardarUsr}/>}
              {subConfig==="feriados"&&<ConfigFeriados feriados={feriados} onSave={guardarFeriados}/>}
              {subConfig==="remitos"&&<HistorialRemitos/>}
              {subConfig==="firmados"&&<RemitasFirmadas pedidos={pedidos} usuarios={usuarios}/>}
              {subConfig==="borrado"&&<ConfigBorrado reservas={reservas} onBorrar={borrarReservas}/>}
            </div>
          )}

        </main>
      </div>

      {toast&&(
        <div className={"fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-xl shadow-xl text-white text-sm font-semibold "+(toast.c==="red"?"bg-red-600":"bg-emerald-600")}>
          {toast.msg}
        </div>
      )}

      <ModalMail r={mail} espacios={espacios} usuarios={usuarios} onClose={()=>setMail(null)}/>
    </div>
  );
}